 const prepared=await Promise.all(data.buildings.map(async b=>{const [full,hidden]=await Promise.all([load(base+b.exports.full.file),load(base+b.exports.walls.file)]);if([full,hidden].some((im,i)=>im.width!==b.exports[i?'walls':'full'].dimensions[0]||im.height!==b.exports[i?'walls':'full'].dimensions[1]))throw Error('S012 source dimensions changed');return{b,full,hidden};}));
 const objects=addSprites(prepared.map(({b,full})=>['section-s012:'+b.id,full,b.p,b.anchor,1,b.rect,{sceneryKind:'building',sourceAsset:'SECTION-S012:'+b.id,sourceParcel:b.parcel,uniquePremise:true,cutawayEligible:true}]));
 for(let i=0;i<prepared.length;i++){const{b,hidden}=prepared[i],o=objects[i];const q=project(b.p);o.roofHidden={...o,im:hidden,anchor:b.hiddenAnchor,bounds:[q.x-b.hiddenAnchor[0],q.y-b.hiddenAnchor[1],hidden.width,hidden.height],lightSource:o.id+':walls'};lightAnchors[o.id]=b.panes.length?b.windowCentres:[];lightAnchors[o.id+':walls']=b.panes.length?b.hiddenWindowCentres:[];CITY_GLASS[o.sourceAsset]={size:b.exports.full.dimensions,windows:b.panes,suppressed:b.windowCentres.map(p=>p.slice(0,2))};CITY_GLASS[o.id+':walls']={size:b.exports.walls.dimensions,windows:b.hiddenPanes,suppressed:b.hiddenWindowCentres.map(p=>p.slice(0,2))};}
 return Object.freeze({data,objects,replaces:r=>data.buildings.some(b=>b.rect.every((v,i)=>Math.abs(v-r[i])<.000001)),report:()=>({id:data.id,ready:true,uniquePremises:2,retiredParcels:data.buildings.map(b=>b.parcel),originalFootprintsRetained:true,buildingsMoved:0,navigationChanged:false,newDoors:0,roofLayersSeparate:true,creativeAcceptance:false})});
